const items = $input.all();

const validRecords = [];
const invalidRecords = [];

for (const item of items) {
  const rawText = item.json.text || "";

  // Extract employee fields from the LLM response
  const getField = (label) => {
    const regex = new RegExp(
      `(?:^|\\n)\\s*[-*]?\\s*${label}\\s*:\\s*(.*)`,
      "i"
    );

    const match = rawText.match(regex);
    return match ? match[1].trim() : "";
  };

  const employee = {
    employee_id: getField("Employee ID"),
    full_name: getField("Full Name"),
    email: getField("Email").toLowerCase(),
    phone: getField("Phone"),
    department: getField("Department"),
    job_title: getField("Job Title"),
    salary_inr: getField("Salary \\(INR\\)"),
    joining_date: getField("Joining Date")
  };

  const errors = [];

  // Clean text fields
  for (const key of [
    "employee_id",
    "full_name",
    "department",
    "job_title"
  ]) {
    employee[key] = employee[key].replace(/\s+/g, " ").trim();
  }

  // Clean email
  employee.email = employee.email.replace(/\s+/g, "");

  // Clean phone: preserve digits and optional country code
  employee.phone = employee.phone.replace(/[\s()-]/g, "");

  // Clean salary: remove currency symbols and commas
  const salaryText = employee.salary_inr.replace(/[₹,\s]/g, "");
  const salary = Number(salaryText);

  employee.salary_inr = salaryText === "" ? null : salary;

  // Validate required fields
  if (!employee.employee_id) errors.push("Missing employee ID");
  if (!employee.full_name) errors.push("Missing full name");
  if (!employee.department) errors.push("Missing department");
  if (!employee.job_title) errors.push("Missing job title");

  // Validate email
  if (
    !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(employee.email)
  ) {
    errors.push("Invalid email");
  }

  // Validate Indian mobile number: 10 digits, optionally +91
  if (!/^(?:\+91)?[6-9]\d{9}$/.test(employee.phone)) {
    errors.push("Invalid Indian mobile number");
  }

  // Validate salary
  if (
    employee.salary_inr === null ||
    !Number.isFinite(salary) ||
    salary <= 0
  ) {
    errors.push("Invalid salary");
  }

  // Normalize joining date to YYYY-MM-DD
  const dateMatch = employee.joining_date.match(
    /^(\d{1,2})\s+([A-Za-z]+)\s+(\d{4})$/
  );

  if (dateMatch) {
    const months = {
      january: "01", february: "02", march: "03",
      april: "04", may: "05", june: "06",
      july: "07", august: "08", september: "09",
      october: "10", november: "11", december: "12"
    };

    const day = dateMatch[1].padStart(2, "0");
    const month = months[dateMatch[2].toLowerCase()];
    const year = dateMatch[3];

    if (month) {
      employee.joining_date = `${year}-${month}-${day}`;
    } else {
      errors.push("Invalid joining date");
    }
  } else if (
    !/^\d{4}-\d{2}-\d{2}$/.test(employee.joining_date)
  ) {
    errors.push("Invalid joining date");
  }

  employee.status = errors.length === 0 ? "valid" : "invalid";
  employee.errors = errors;

  if (errors.length === 0) {
    validRecords.push({ json: employee });
  } else {
    invalidRecords.push({ json: employee });
  }
}

// Output both groups in a single item
return [{
  json: {
    total_records: items.length,
    valid_count: validRecords.length,
    invalid_count: invalidRecords.length,
    valid_records: validRecords.map(item => item.json),
    invalid_records: invalidRecords.map(item => item.json)
  }
}];
